func serversForGroup(addr string, group []*Config) ([]caddy.Server, error) {
	servers := make([]caddy.Server, 0, group[0].NumSocks)
	for range group[0].NumSocks {
		s, err := newServerForAddr(addr, group)
		if err != nil {
			return nil, err
		}
		if s != nil {
			servers = append(servers, s)
		}
	}
	return servers, nil
}

func newServerForAddr(addr string, group []*Config) (caddy.Server, error) {
	switch tr, _ := parse.Transport(addr); tr {
	case transport.DNS:
		return NewServer(addr, group)
	case transport.TLS:
		return NewServerTLS(addr, group)
	case transport.QUIC:
		return NewServerQUIC(addr, group)
	case transport.GRPC:
		return NewServergRPC(addr, group)
	case transport.HTTPS:
		return NewServerHTTPS(addr, group)
	}
	return nil, nil
}

